export type OnyxThemeToken = keyof typeof ONYX_THEME_VARIABLES;
export type OnyxCSSVariable = (typeof ONYX_THEME_VARIABLES)[OnyxThemeToken];
export type OnyxThemeVariables = Partial<
  Record<OnyxThemeToken | OnyxCSSVariable | `--onyx-${string}`, string>
>;
export type OnyxTheme = 'dark' | 'light';
export type OnyxDensity = 'compact' | 'comfortable';
export const ONYX_DEFAULT_THEME = Object.fromEntries(
  Object.entries(ONYX_THEME_VARIABLES).map(([key, css]) => [
    key,
    (
      {
        ...ONYX_PALETTE,
        ...ONYX_SEMANTIC_DARK,
        ...ONYX_COMPONENT_TOKENS,
        ...ONYX_DENSITY_COMPACT,
      } as Record<string, string>
    )[css] ?? 'initial',
  ]),
) as Record<OnyxThemeToken, string>;
export function mergeOnyxThemeVariables(
  ...sources: OnyxThemeVariables[]
): OnyxThemeVariables {
  return Object.assign({}, ...sources);
}
/** Only overrides are inline, allowing ancestor theme/density CSS to remain live. */
export function createOnyxThemeStyleMap(
  variables: OnyxThemeVariables = {},
): Record<string, string> {
  return Object.fromEntries(
    Object.entries(variables).map(([key, value]) => [
      (ONYX_THEME_VARIABLES as Record<string, string>)[key] ?? key,
      value!,
    ]),
  );
}

/** Instance geometry/state belongs to the implementation, not the theme API. */
export const ONYX_PRIVATE_VARIABLES = ["--onyx-color-picker-black", "--onyx-color-picker-hue", "--onyx-toast-index", "--onyx-color-picker-white", "--onyx-display-bg", "--onyx-display-border", "--onyx-display-fg", "--onyx-display-solid", "--onyx-display-solid-fg", "--onyx-listbox-row-height", "--onyx-resolved-font-size", "--onyx-split-size", "--onyx-tree-depth", "--onyx-tree-row-height"] as const;

/** Alias dependency closure; CSS rebinds only inherited defaults, not consumer values. */
export function getOnyxThemeRebindings(variables: OnyxThemeVariables = {}): string[] {
  const explicit = createOnyxThemeStyleMap(variables);
  const affected = new Set(Object.keys(explicit));
  const aliases = { ...ONYX_SEMANTIC_DARK, ...ONYX_SEMANTIC_LIGHT };
  // Both themes can use different dependencies for the same public alias.
  for (let changed = true; changed;) {
    changed = false;
    for (const map of [ONYX_SEMANTIC_DARK, ONYX_SEMANTIC_LIGHT]) {
      for (const [name, value] of Object.entries(map)) {
        if (!affected.has(name) && [...value.matchAll(/var\((--onyx-[a-z0-9-]+)/g)].some(match => affected.has(match[1]!))) {
          affected.add(name); changed = true;
        }
      }
    }
  }
  return Object.keys(aliases).filter(name => affected.has(name) && !(name in explicit));
}
